        address pool = _getPoolFromPosition(positionId);
        if (pool == address(0)) return 0;

        (, int24 currentTick, , , , , ) = IPancakeSwapPoolState(pool).slot0();

        PositionRangeStatusCheck currentStatus = _getPositionStatus(
