                            hex"e34f199b19b2b4f47f68442619d555527d244f78a3297ea89325f843f87b8b54" // POOL_INIT_CODE_HASH
                        )
                    )
                )
            )
        );
    }

    function walletCondition(
        address _wallet,
        uint32 _id
    ) public view returns (Condition memory) {
        return conditions[_wallet][_id];
    }
}

